// Owner's rule: no Claude identifiers in PRs, issues or comments, with NO
// exceptions. That includes the "Requested by ... · project thread" header the
// projects harness adds to every PR: it was kept here until 2026-11-03 under an
// exception the owner never asked for, and is now stripped like everything else.
// Strips any claude.ai link, the attribution marker and header, and the
// "Generated by/with Claude Code" footers.

const FOOTER = /^\s*(🤖\s*)?_?Generated (by|with) (\[Claude Code\]\([^)]*\)|Claude Code)_?\s*$/i;
// Any claude.ai URL, with or without a scheme. The bare word "claude.ai" (no
// path, no scheme) is left alone so rules like this one can still be written.
// The path stops before trailing punctuation so a sentence's full stop survives,
// and the host must end there (claude.ai, claude.ai/..., not claude.ai.example).
const PATH = String.raw`(?:[^\s<>\]]*[^\s<>\].,;:!?)*_\x60])?`;
// With a scheme: any claude.ai URL. Without one: only a claude.ai/... path
// (a pasted session or project link), never the bare word claude.ai.
const URL = String.raw`(?:https?:\/\/(?:www\.)?claude\.ai(?![\w-]|\.\w)(?:[\/?#]${PATH})?|(?<![\w.\/-])(?:www\.)?claude\.ai\/${PATH})`;
const LINKED = new RegExp(String.raw`\[([^\]]*)\]\(\s*<?${URL}>?(?:\s+"[^"]*")?\s*\)`, 'gi');
const BARE = new RegExp(String.raw`<${URL}>|\(${URL}\)|${URL}`, 'gi');
// The harness's two-line attribution block: an HTML marker, then the header.
const MARKER = /^\s*<!--.*claude-projects-attribution.*-->\s*$/i;
const HEADER = /^\s*_?Requested by\b.*\bproject thread\b/i;

function clean(body) {
  if (!body) return body;
  // A removed line leaves a null, so the trim below knows where text was cut.
  const out = [];
  let touched = false;
  for (const line of body.split('\n')) {
    // The header goes whether or not its link is one the URL pattern knows.
    if (MARKER.test(line) || FOOTER.test(line) || HEADER.test(line)) { touched = true; out.push(null); continue; }
    const kept = line.replace(LINKED, '$1').replace(BARE, '');
    if (kept !== line) touched = true;
    out.push(kept !== line && !kept.trim() ? null : kept);
  }
  // Text with nothing to strip is left exactly as written.
  if (!touched) return body;
  // At each end, drop removed lines and blank lines, and one "---" rule only
  // when it sat between removed text and that end (the footer's or header's
  // own rule). A rule of the author's own, with nothing removed beyond it, stays.
  trim(out, true);
  trim(out, false);
  return out.filter((l) => l !== null).join('\n');
}

function trim(lines, atEnd) {
  let cut = false;
  while (lines.length) {
    const l = lines[atEnd ? lines.length - 1 : 0];
    if (l === null) cut = true;
    else if (cut && /^\s*---\s*$/.test(l)) cut = false; // one rule per cut, no more
    else if (!/^\s*$/.test(l)) break;
    if (atEnd) lines.pop(); else lines.shift();
  }
}

async function fix(kind, item, update, core) {
  const body = clean(item.body);
  if (body === item.body) return;
  await update(body);
  core.info(`Cleaned ${kind} ${item.html_url}`);
}

async function run({ github, context, core }) {
  const { owner, repo } = context.repo;
  const p = context.payload;
  const issue = (it) => fix('issue/PR', it, (body) =>
    github.rest.issues.update({ owner, repo, issue_number: it.number, body }), core);
  const comment = (c) => fix('comment', c, (body) =>
    github.rest.issues.updateComment({ owner, repo, comment_id: c.id, body }), core);
  const reviewComment = (c) => fix('review comment', c, (body) =>
    github.rest.pulls.updateReviewComment({ owner, repo, comment_id: c.id, body }), core);
  const review = (pr, r) => fix('review', r, (body) =>
    github.rest.pulls.updateReview({ owner, repo, pull_number: pr, review_id: r.id, body }), core);

  switch (context.eventName) {
    case 'pull_request_target': return issue(p.pull_request);
    case 'issues': return issue(p.issue);
    case 'issue_comment': return comment(p.comment);
    case 'pull_request_review_comment': return reviewComment(p.comment);
    case 'pull_request_review': return review(p.pull_request.number, p.review);
    case 'workflow_dispatch': {
      // Sweep everything already posted.
      const all = (fn, args) => github.paginate(fn, { owner, repo, per_page: 100, ...args });
      for (const it of await all(github.rest.issues.listForRepo, { state: 'all' })) await issue(it);
      for (const c of await all(github.rest.issues.listCommentsForRepo)) await comment(c);
      for (const c of await all(github.rest.pulls.listReviewCommentsForRepo)) await reviewComment(c);
      for (const pr of await all(github.rest.pulls.list, { state: 'all' }))
        for (const r of await all(github.rest.pulls.listReviews, { pull_number: pr.number }))
          if (r.body) await review(pr.number, r);
      return;
    }
  }
}

module.exports = { clean, run };
